# Master Script: run_all.R
#
# Author:   Getachew Derbew Belay
# Date:     October 2026
# Platform: R 4.5.2
# Contact:  derbew1953@gmail.com / d610113006@tmu.edu.tw
#
# Purpose:  Execute the entire Paper 2 reproducibility pipeline in sequential
#           order, from data processing (Script 00) to the final figure and
#           table generation (Script 08). It times each script and reports
#           pass/fail status, halting the pipeline if any script fails.
#
#
# Produces: All outputs generated by Scripts 00-08 (Tables 1-3, Figures 1-6,
#           Supplementary Figures S1-S9, Supplementary Tables S1-S6).
#
# Save as:  run_all.R
# Save in:  ~/TCGA_Local_Storage/TCGA NSCLC Project/
#
# Depends:  00_base_setup.R, 01_correlation.R, 02_six_model_comparison.R,
#           03_expression_signature.R, 04_methylation_signature.R,
#           04b_methylation_hr_rescaling.R, 05_clinical_utility.R,
#           06_table1.R, 07_figureS8_S9.R, 08_provenance_figure1.R
#
# Seeds:    Defined internally within each individual script.
# ==============================================================================

project_dir <- "~/TCGA_Local_Storage/TCGA NSCLC Project"
if (!dir.exists(project_dir)) stop("Project directory not found: ", project_dir)
setwd(project_dir)
options(warn = 1)

cat("\n===============================================================\n")
cat("PAPER 2 - FULL ANALYSIS PIPELINE (WITH ISSUE-1 FIX)\n")
cat("Started     :", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "\n")
cat("===============================================================\n\n")

# Define the 10 scripts in exact execution order
runall_scripts <- c(
  "00_base_setup.R",                  # Cohort assembly, utilities, promoter mapping
  "01_correlation.R",                 # Outputs: Table 2, Table S2, Figures 2, 3, S1
  "02_six_model_comparison.R",        # Outputs: Table 3, Figures 4, S4, S5
  "03_expression_signature.R",        # Outputs: Table S3, Figures 5, S2, S3, S6
  "04_methylation_signature.R",       # Outputs: Tables S4, S5, Figure S7
  "04b_methylation_hr_rescaling.R",   # NEW: Outputs: Table S6 (corrected HRs)
  "05_clinical_utility.R",            # Outputs: Figure 6
  "06_table1.R",                      # Outputs: Table 1
  "07_figureS8_S9.R",                 # Outputs: Figures S8, S9 (revised S8)
  "08_provenance_figure1.R"           # Copies Figure 1 to directory
)

# Verify all scripts exist before starting
missing_scripts <- runall_scripts[!file.exists(runall_scripts)]
if (length(missing_scripts) > 0) {
  stop("The following required scripts are missing from the project directory:\n",
       paste0("  - ", missing_scripts, collapse = "\n"))
}
cat("All", length(runall_scripts), "scripts found. Starting pipeline...\n\n")

# Data-frame to collect results
runall_results <- data.frame(
  Script  = character(),
  Status  = character(),
  Seconds = numeric(),
  Message = character(),
  stringsAsFactors = FALSE
)

# Run each script in sequence
for (runall_script in runall_scripts) {
  cat("---------------------------------------------------------------\n")
  cat("Running:", runall_script, "\n")
  cat("---------------------------------------------------------------\n")
  
  t0     <- Sys.time()
  status <- "OK"
  msg    <- ""
  
  tryCatch({
    source(runall_script, echo = FALSE, local = FALSE)
  }, error = function(e) {
    status <<- "FAILED"
    msg    <<- conditionMessage(e)
    cat("\n  *** ERROR in ", runall_script, " ***\n", sep = "")
    cat("  ", msg, "\n", sep = "")
  })
  
  elapsed <- as.numeric(difftime(Sys.time(), t0, units = "secs"))
  cat("\n  Status :", status, "\n")
  cat("  Time   :", sprintf("%.1f", elapsed), "seconds\n\n")
  
  runall_results <- rbind(runall_results, data.frame(
    Script  = runall_script,
    Status  = status,
    Seconds = round(elapsed, 1),
    Message = msg,
    stringsAsFactors = FALSE
  ))
  
  if (status == "FAILED") {
    cat("Pipeline halted at ", runall_script, ".\n", sep = "")
    break
  }
}

# Summary
cat("\n===============================================================\n")
cat("PIPELINE SUMMARY\n")
cat("===============================================================\n")
print(runall_results, row.names = FALSE)

# Write summary to disk for the record
write.csv(runall_results, "run_all_summary.csv", row.names = FALSE)
cat("\nSummary written to run_all_summary.csv\n")

cat("\nFinished :", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "\n")
cat("===============================================================\n")

# Post-run verification: confirm the corrected Table S6 exists
if (file.exists("TableS6_Corrected_HR.csv")) {
  cat("\nCorrected HR table found: TableS6_Corrected_HR.csv\n")
  ts6 <- read.csv("TableS6_Corrected_HR.csv")
  cat("Rows:", nrow(ts6), " | Scales available:",
      paste(unique(ts6$Scale), collapse = ", "), "\n")
} else {
  cat("\nWARNING: TableS6_Corrected_HR.csv was not produced.\n")
  cat("Check that 04b_methylation_hr_rescaling.R ran to completion.\n")
}

if (file.exists("FigureS8_Forest_Expression_vs_Methylation.pdf")) {
  cat("Corrected Figure S8 found: FigureS8_Forest_Expression_vs_Methylation.pdf\n")
} else {
  cat("WARNING: FigureS8_Forest_Expression_vs_Methylation.pdf was not produced.\n")
}